import assert from 'node:assert/strict';
import {createServer} from 'node:http';
import {readFileSync,existsSync,mkdirSync,writeFileSync} from 'node:fs';
import {resolve,dirname,extname} from 'node:path';
import {fileURLToPath,pathToFileURL} from 'node:url';
const root=resolve(dirname(fileURLToPath(import.meta.url)),'..');
const {checkout}=JSON.parse(readFileSync(resolve(root,'.work/source.json'),'utf8'));
const {chromium}=await import(pathToFileURL(resolve(checkout,'apps/web/node_modules/playwright/index.mjs')).href);
const directory=resolve(root,process.env.CONVERSATION_BUNDLE??'.work/services');
const mime={'.html':'text/html','.js':'text/javascript','.css':'text/css','.wasm':'application/wasm','.woff2':'font/woff2','.svg':'image/svg+xml','.json':'application/json'};
const server=createServer((request,response)=>{const path=resolve(directory,'.'+decodeURIComponent(new URL(request.url,'http://localhost').pathname));if(!path.startsWith(directory+'/')){response.writeHead(403);response.end();return;}if(!existsSync(path)){response.writeHead(404);response.end();return;}response.setHeader('Content-Type',mime[extname(path)]??'application/octet-stream');response.end(readFileSync(path));});
await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));
const origin=`http://127.0.0.1:${server.address().port}`;
const browser=await chromium.launch({headless:true});
const page=await browser.newPage({viewport:{width:900,height:1100}});
const errors=[],network=[],consoleErrors=[];
page.on('pageerror',error=>errors.push(error.message));page.on('console',message=>{if(message.type()==='error')consoleErrors.push(message.text());});
page.on('request',request=>{if(!request.url().startsWith(origin)&&!request.url().startsWith('data:')&&!request.url().startsWith('blob:'))network.push(request.url());});
page.on('websocket',socket=>network.push(socket.url()));
await page.addInitScript(()=>{window.__bridge=[];window.webkit={messageHandlers:{tabConversation:{postMessage(message){window.__bridge.push(message);if(message.type!=='action')return;const action=message.action;const number=action.input?.number;if(action.kind==='pullRequestPreview'){setTimeout(()=>window.TabConversation.resolve(number===43?{requestId:message.requestId,ok:false,error:"GitHub CLI isn't installed"}:{requestId:message.requestId,ok:true,result:{projectId:'project',repository:'example/repo',number:42,title:'Existing server PR',url:'https://github.com/example/repo/pull/42',author:{login:'author',name:null,avatarUrl:null},state:'open',isDraft:true,createdAt:'2026-10-31T10:00:00Z'}}),80);}else{queueMicrotask(()=>window.TabConversation.resolve({requestId:message.requestId,ok:false,error:'Unexpected fixture action: '+action.kind}));}}}}};});
const base={bridgeVersion:1,sessionId:'session',projectId:'project',environmentId:'project',connectionState:'live',revision:1,theme:'light',cwd:'/workspace',status:'idle',turns:[],items:[{id:'answer',kind:'assistant',text:'[Review PR](https://github.com/example/repo/pull/42)',isComplete:true}],messages:[],projects:[{id:'project',environmentId:'project',title:'Project',workspaceRoot:'/workspace'}],font:{interfaceSize:16,promptSize:14,codeSize:13},capabilities:{nativeActions:true,pullRequestPreview:true}};
const checks=[];
try{
 await page.goto(origin+'/index.html',{waitUntil:'networkidle'});await page.waitForFunction(()=>window.TabConversation);
 await page.evaluate(snapshot=>window.TabConversation.update(snapshot),base);
 await page.getByRole('link',{name:'Review PR',exact:true}).waitFor();
 await page.getByRole('link',{name:'Review PR',exact:true}).hover();await page.waitForTimeout(500);
 assert.equal(await page.evaluate(()=>window.__bridge.filter(item=>item.type==='action'&&item.action.kind==='pullRequestPreview').length),0);
 checks.push('unknown repository identity does not fabricate a preview or eager GitHub query');
 const linked={...base,revision:2,projects:[{...base.projects[0],originURL:'https://github.com/example/repo.git'}]};
 await page.mouse.move(850,1000);await page.evaluate(snapshot=>window.TabConversation.update(snapshot),linked);
 await page.getByRole('link',{name:'Review PR',exact:true}).hover();
 await page.getByText('Existing server PR',{exact:true}).waitFor({timeout:10000});
 assert.ok(await page.getByText('example/repo',{exact:true}).count());assert.ok(await page.getByText('Draft',{exact:true}).count());assert.ok(await page.getByText('author',{exact:true}).count());
 const request=await page.evaluate(()=>window.__bridge.find(item=>item.type==='action'&&item.action.kind==='pullRequestPreview').action);
 assert.deepEqual(request.input,{projectId:'project',host:'github.com',repository:'example/repo',number:42});
 assert.equal(request.environmentId,'project');checks.push('late actual origin metadata enables the unchanged source PR card with scoped metadata');
 await page.mouse.move(850,1000);
 const sshLinked={...linked,revision:3,projects:[{...linked.projects[0],originURL:'ssh://github.com/example/repo.git'}]};
 await page.evaluate(snapshot=>window.TabConversation.update(snapshot),sshLinked);
 await page.getByRole('link',{name:'Review PR',exact:true}).hover();
 await page.getByText('Existing server PR',{exact:true}).waitFor({timeout:10000});
 checks.push('credential-free normalized SSH origin uses the actual source repository matcher');
 await page.mouse.move(850,1000);
 const unavailable={...sshLinked,revision:4,items:[{...base.items[0],text:'[Unavailable PR](https://github.com/example/repo/pull/43)'}]};
 await page.evaluate(snapshot=>window.TabConversation.update(snapshot),unavailable);
 await page.getByRole('link',{name:'Unavailable PR',exact:true}).hover();
 await page.getByText('https://github.com/example/repo/pull/43',{exact:true}).waitFor({timeout:10000});
 assert.equal(await page.getByText('Existing server PR',{exact:true}).count(),0);
 checks.push('GitHub service failure preserves the source URL fallback without renderer failure');
 const diagnostics=await page.evaluate(()=>window.__bridge.filter(item=>item.type==='error'||item.type==='renderDiagnostic'&&item.scope!=='resize-observer'));
 assert.deepEqual(diagnostics,[]);assert.deepEqual(errors,[]);assert.deepEqual(consoleErrors,[]);assert.deepEqual(network,[]);
 checks.push('no unexpected renderer errors, network or upstream service startup');
 const output=resolve(root,'.work/qa/inline-pr');mkdirSync(output,{recursive:true});await page.screenshot({path:resolve(output,'inline-pr.png'),fullPage:true});writeFileSync(resolve(output,'report.json'),JSON.stringify({checks,errors,network,diagnostics},null,2));
 process.stdout.write(JSON.stringify({checks,errors,network,diagnostics},null,2)+'\n');
}finally{await browser.close();server.close();}
